CREATE OR ALTER TRIGGER dbo.trg_account_transaction_audit ON dbo.account_transaction AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; INSERT dbo.account_tx_audit(TransactionID,ActionName,AccountID,Amount,TransactionType,ChangedBy) SELECT i.TransactionID,'INSERT',i.AccountID,i.Amount,i.TransactionType,ORIGINAL_LOGIN() FROM inserted i LEFT JOIN deleted d ON d.TransactionID=i.TransactionID WHERE d.TransactionID IS NULL; INSERT dbo.account_tx_audit(TransactionID,ActionName,AccountID,Amount,TransactionType,ChangedBy) SELECT d.TransactionID,'DELETE',d.AccountID,d.Amount,d.TransactionType,ORIGINAL_LOGIN() FROM deleted d LEFT JOIN inserted i ON i.TransactionID=d.TransactionID WHERE i.TransactionID IS NULL; INSERT dbo.account_tx_audit(TransactionID,ActionName,AccountID,Amount,TransactionType,ChangedBy) SELECT i.TransactionID,'UPDATE',i.AccountID,i.Amount,i.TransactionType,ORIGINAL_LOGIN() FROM inserted i JOIN deleted d ON d.TransactionID=i.TransactionID; END;
GO
CREATE OR ALTER VIEW dbo.vw_savings_accounts AS SELECT AccountID,AccountName,Balance FROM dbo.accounts WHERE AccountType='Savings';
GO
CREATE OR ALTER TRIGGER dbo.trg_savings_balance_guard ON dbo.vw_savings_accounts INSTEAD OF UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted WHERE Balance<0) THROW 51011,'Update blocked: savings balance cannot be negative.',1; UPDATE a SET AccountName=i.AccountName,Balance=i.Balance FROM dbo.accounts a JOIN inserted i ON i.AccountID=a.AccountID WHERE a.AccountType='Savings'; END;